INSERT INTO definition VALUES('health.weight',7,replace('{\n  "meta": {\n    "facet_type": "health.weight",\n    "definition_version": 7,\n    "kind": "reading",\n    "family": "body",\n    "classification": "Sensitive",\n    "validation_mode": "strict",\n    "source_schema": "records/health.weight",\n    "time_semantics": {\n      "fact_time": {"pointer": "/date", "layout": "2006-01-02 15:04", "zone": "Australia/Sydney",\n        "zone_pointer": "/source_time/offset"}\n    },\n    "identity_key": ["/id"],\n    "min_binding_assurance": "medium"\n  },\n  "handling": {\n    "label": "{/kg} kg"\n  },\n  "schema": {\n    "$schema": "https://json-schema.org/draft/2020-12/schema",\n    "description": "One body weight, from a records file. Two records sources write it: the Fitbit weight log export, extracted by scripts/extract-fitbit-weight.py, and weights noted in the blood pressure diary, read into records by hand. Values are the source''s own figures. Version 6 adds handling.label, a short label a page draws a row as, every rule unchanged. Version 7 requires source_time, every other rule unchanged.",\n    "type": "object",\n    "required": ["id", "date", "kg", "source_time"],\n    "properties": {\n      "source_time": {"type": "object", "description": "How the fact time, `date`, was read: value is the wall clock as said, zone the zone it was said in (an IANA name when the writer knows one, else the offset again), offset the offset from UTC it had then, and basis who decided the zone (source when the person''s own client or browser names it, or a records file states it; configuration when the writer''s setting does). The fact time is `date` read at offset. Required: the records files state Australia/Sydney, the offset for the date and basis source, and the Workbench form sends the browser''s zone.", "required": ["value", "zone", "offset", "basis"], "additionalProperties": false, "properties": {"value": {"type": "string", "minLength": 1, "description": "The fact time as the source supplied it, as text and never rewritten: a date, a wall clock, an RFC 3339 string, or an epoch as its digits.", "examples": ["2026-10-17", "2026-10-20T20:00:00+11:00", "1792269840000"]}, "zone": {"type": "string", "minLength": 1, "pattern": "^([A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)*|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$", "description": "The zone value is read in, and nothing else: an IANA name when one is known, UTC for a value that is UTC, else a fixed offset +HH:MM or -HH:MM. The gate refuses a name that is no zone.", "examples": ["Australia/Sydney", "UTC", "+01:00"]}, "offset": {"type": "string", "pattern": "^[+-]([01][0-9]|2[0-3]):[0-5][0-9]$", "description": "The offset from UTC value had at that moment in zone, +HH:MM or -HH:MM, which names one instant even in an hour the zone repeats. A writer that cannot tell it refuses rather than guess.", "examples": ["+01:00", "+11:00"]}, "basis": {"type": "string", "enum": ["source", "configuration", "assumption"], "description": "Who decided the zone. source: the source supplied it with the value, or the value is UTC by the source''s own definition. configuration: a setting a person made for this source names it. assumption: the importer or writer chose it, with nothing behind it but its own default or the Definition''s zone, and logged that it did."}}},\n      "bmi": {"type": "number", "description": "Body mass index as Fitbit computed it, the export''s fourth column. Fitbit rows only, and only when the log has one.", "examples": [25.31]},\n      "date": {"type": "string", "minLength": 1, "description": "When the weight was logged, local Sydney time to the minute, or at the offset source_time names. For Fitbit rows the extractor rewrites logged_as in this form; diary rows give the date and time read from the diary. This is the fact time.", "examples": ["2026-01-24 06:33"]},\n      "id": {"type": "string", "minLength": 1, "description": "The records row''s id. Fitbit rows are fitbit: and the log''s minute, with :2 and up added when two logs share a minute; diary rows carry the diary''s own prefix and the day.", "examples": ["fitbit:2026-01-24T06:33"]},\n      "kg": {"type": "number", "description": "Body weight in kilograms as the source wrote it. The Fitbit extractor refuses a log whose unit column is not kilograms.", "examples": [82.4]},\n      "logged_as": {"type": "string", "minLength": 1, "description": "The Fitbit export''s log time, first column, verbatim. Fitbit rows only.", "examples": ["January 24, 2026 at 06:33AM"]},\n      "source_note": {"type": "string", "minLength": 1, "description": "Where the row came from, in words. The Fitbit extractor writes a fixed note; diary rows carry the reader''s note.", "examples": ["Fitbit weight log (Google Takeout export)"]}\n    },\n    "additionalProperties": false\n  }\n}\n','\n',char(10)));
INSERT INTO definition VALUES('test.gone',1,replace('{\n  "meta": {\n    "facet_type": "test.gone",\n    "definition_version": 1,\n    "classification": "Normal",\n    "validation_mode": "strict",\n    "source_schema": "test/gone",\n    "time_semantics": {"fact_time": {"pointer": "/at", "layout": "2006-01-02T15:04:05Z07:00", "zone": "UTC"}},\n    "identity_key": ["/id"]\n  },\n  "schema": {\n    "$schema": "https://json-schema.org/draft/2020-12/schema",\n    "type": "object",\n    "required": ["id", "at", "value"],\n    "properties": {\n      "id": {"type": "string", "minLength": 1},\n      "at": {"type": "string", "minLength": 1},\n      "value": {"type": "number"}\n    },\n    "additionalProperties": false\n  }\n}','\n',char(10)));
