CREATE INDEX facet_index_by_time   ON facet_index (fact_time);
CREATE INDEX facet_index_by_type   ON facet_index (type, fact_time);
CREATE INDEX facet_index_by_bucket ON facet_index (bucket_id);
CREATE INDEX anam_event_by_time ON anam_event_index (anam_time, seq);
CREATE INDEX facet_edge_by_facet ON facet_edge (facet_id);
CREATE VIEW span_head AS
  SELECT span_id, v, covers_w, value_hash, minted_at
  FROM checkpoint c
  WHERE v = (SELECT MAX(v) FROM checkpoint WHERE span_id = c.span_id);
CREATE TRIGGER checkpoint_value_no_update
BEFORE UPDATE ON checkpoint_value
BEGIN SELECT RAISE(ABORT, 'checkpoint_value is insert-only'); END;
CREATE TRIGGER registered_definition_no_update
BEFORE UPDATE ON registered_definition
BEGIN SELECT RAISE(ABORT, 'registered_definition is immutable'); END;
CREATE TRIGGER registered_definition_no_delete
BEFORE DELETE ON registered_definition
BEGIN SELECT RAISE(ABORT, 'registered_definition is immutable'); END;
